import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
test('actual pinned browser expires a session on native tab return and restores the protected destination after signing in',{timeout:30000},async()=>{
  const server=await testServer();let child;
  try{
    const request=server.agent();await request('POST','/auth/signup',{name:'Session Owner',email:'session-owner@example.test',password:'correct session password'});
    const org=(await request('POST','/orgs',{name:'Session organization'})).data.organization;
    const project=(await request('POST','/orgs/'+org.id+'/projects',{key:'SESSION',name:'Session project'})).data.project;
    const issue=(await request('POST','/projects/'+project.id+'/issues',{title:'Session return issue'})).data.issue;
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./session-browser.py',import.meta.url)),JSON.stringify({url:server.url,issueId:issue.id})],{detached:true});
      let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Session browser exceeded bounded deadline'));},25000);
      child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);
      child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
    });
    assert.equal(result.code,0,result.stderr);const proof=JSON.parse(result.stdout.trim());
    assert.equal(proof.crossTabExpired,true);assert.equal(proof.restoredDestination,true);assert.equal(proof.manualCheck,true);
  }finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}await server.close();}
});
